(() => {
  const TAU = Math.PI * 2;
  const BASE_PREFIX = 'data:image/svg+xml;charset=utf-8;base64,';
  const wheelOptions = new Map([
    [
      "cash_100",
      {
        lines: ["100 USDT", "Cash"],
        colors: ["#77bd72", "#2e6842"],
        iconSvg: "",
      },
    ],
    [
      "dogs_50",
      {
        lines: ["50 USDT", "DOGS"],
        colors: ["#41c9d8", "#1592aa"],
        iconSvg: "",
      },
    ],
    [
      "loss_50",
      {
        lines: ["50% First Order", "Loss Protection"],
        note: "(Max 200 USDT)",
        colors: ["#43595f", "#24343c"],
        fontSize: 23,
        textRadiusRatio: 0.55,
        iconSvg: "",
      },
    ],
    [
      "loss_100",
      {
        lines: ["100% First Order", "Loss Protection"],
        note: "(Max 70 USDT)",
        colors: ["#40585d", "#20333a"],
        fontSize: 22,
        textRadiusRatio: 0.55,
        iconSvg: "",
      },
    ],
    [
      "rebate_7d",
      {
        lines: ["7-Day 100%", "Fee Rebate"],
        note: "(Max 50 USDT)",
        colors: ["#2e8e96", "#24515c"],
        fontSize: 24,
        textRadiusRatio: 0.54,
        iconSvg: "",
      },
    ],
    [
      "drop_50",
      {
        lines: ["50", "Drop"],
        colors: ["#49d4df", "#139eb0"],
        iconSvg: "",
      },
    ],
    [
      "deposit_bonus",
      {
        lines: ["50% Deposit", "Bonus"],
        note: "(Max 50 USDT)",
        colors: ["#d6d6df", "#7f818d"],
        fontSize: 23,
        textRadiusRatio: 0.59,
        iconSvg: "",
      },
    ],
    [
      "btc_1000",
      {
        lines: ["1000 USDT", "BTC"],
        colors: ["#ffc943", "#d79121"],
        iconSvg: "",
      },
    ],
  ]);

  class TurntableCanvas extends EventTarget {
    constructor(canvas, optionsMap, config = {}) {
      super();
      this.canvas = canvas;
      this.ctx = canvas.getContext("2d");
      this.config = {
        startAngle: -Math.PI / 2,
        pointerAngle: -Math.PI / 2,
        gapAngle: 0.025,
        petalCornerRatio: 0.055,
        petalSideCurve: 0.045,
        spinDuration: 4300,
        minTurns: 5,
        maxTurns: 7,
        showIconSlots: false,
        ...config,
      };
      this.optionsMap = new Map(optionsMap);
      this.items = this.mapToItems(this.optionsMap);
      this.iconCache = new Map();
      this.rotation = config.initialRotation || 0;
      this.isSpinning = false;
      this.animationFrame = 0;
      this.geometry = null;

      this.resize = this.resize.bind(this);
      this.handlePointer = this.handlePointer.bind(this);
      this.handleKeydown = this.handleKeydown.bind(this);

      this.preloadIcons();
      this.attach();
      this.resize();
    }

    attach() {
      this.canvas.addEventListener("click", this.handlePointer);
      this.canvas.addEventListener("keydown", this.handleKeydown);

      if ("ResizeObserver" in window) {
        this.resizeObserver = new ResizeObserver(this.resize);
        this.resizeObserver.observe(this.canvas);
      } else {
        window.addEventListener("resize", this.resize);
      }
    }

    destroy() {
      cancelAnimationFrame(this.animationFrame);
      this.canvas.removeEventListener("click", this.handlePointer);
      this.canvas.removeEventListener("keydown", this.handleKeydown);
      if (this.resizeObserver) {
        this.resizeObserver.disconnect();
      } else {
        window.removeEventListener("resize", this.resize);
      }
    }

    setOptions(optionsMap) {
      this.optionsMap = new Map(optionsMap);
      this.items = this.mapToItems(this.optionsMap);
      this.iconCache.clear();
      this.preloadIcons();
      this.draw();
    }

    mapToItems(optionsMap) {
      return Array.from(optionsMap, ([key, value]) => ({
        key,
        weight: 1,
        lines: [String(key)],
        colors: ["#48c2cd", "#1f7787"],
        iconSvg: "",
        iconUrl: "",
        ...value,
      }));
    }

    preloadIcons() {
      for (const item of this.items) {
        const source = this.resolveIconSource(item);
        if (!source) {
          continue;
        }

        const image = new Image();
        image.onload = () => this.draw();
        image.onerror = () => {
          this.iconCache.delete(item.key);
        };
        image.src = source;
        this.iconCache.set(item.key, image);
      }
    }

    resolveIconSource(item) {
      if (item.iconSvg && item.iconSvg.trim()) {
        const svg = item.iconSvg.trim();
        if (svg.startsWith("data:image/svg+xml")) {
          return svg;
        }
        return `${BASE_PREFIX}${svg}`;
      }
      return item.iconUrl || "";
    }

    resize() {
      const rect = this.canvas.getBoundingClientRect();
      if (!rect.width || !rect.height) {
        return;
      }

      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      const width = Math.round(rect.width * dpr);
      const height = Math.round(rect.height * dpr);

      if (this.canvas.width !== width || this.canvas.height !== height) {
        this.canvas.width = width;
        this.canvas.height = height;
      }

      this.ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      this.geometry = this.createGeometry(rect.width, rect.height);
      this.draw();
    }

    createGeometry(width, height) {
      const size = Math.min(width, height);
      const outer = size * 0.465;
      const segmentOuter = outer * 0.91;
      const segmentInner = outer * 0.08;
      const centerRadius = outer * 0.255;

      return {
        width,
        height,
        cx: width / 2,
        cy: height / 2,
        outer,
        segmentOuter,
        segmentInner,
        segmentMid: (segmentOuter + segmentInner) / 2,
        segmentWidth: segmentOuter - segmentInner,
        centerRadius,
        petalCornerRadius: outer * this.config.petalCornerRatio,
        iconSize: outer * 0.17,
        iconRadius: outer * 0.69,
        textRadius: outer * 0.52,
        textMaxWidth: outer * 0.34,
      };
    }

    handlePointer(event) {
      const rect = this.canvas.getBoundingClientRect();
      const x = event.clientX - rect.left - this.geometry.cx;
      const y = event.clientY - rect.top - this.geometry.cy;

      if (Math.hypot(x, y) <= this.geometry.centerRadius * 1.12) {
        this.spin();
      }
    }

    handleKeydown(event) {
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        this.spin();
      }
    }

    spin(request = {}) {
      const options =
        typeof request === "string" ? { targetKey: request } : { ...request };

      if (this.isSpinning) {
        return Promise.resolve(this.getSelectedItem());
      }

      const targetKey = options.targetKey || this.pickWeightedKey();
      const targetIndex = this.items.findIndex((item) => item.key === targetKey);
      if (targetIndex < 0) {
        return Promise.reject(new Error(`Unknown wheel item: ${targetKey}`));
      }

      const step = TAU / this.items.length;
      const turns =
        options.turns ||
        randomBetween(this.config.minTurns, this.config.maxTurns);
      const duration = options.duration || this.config.spinDuration;
      const targetCenter = this.config.startAngle + (targetIndex + 0.5) * step;
      const targetRotation = normalize(
        this.config.pointerAngle - targetCenter,
      );
      const currentRotation = normalize(this.rotation);
      const extraRotation = normalize(targetRotation - currentRotation);
      const startRotation = this.rotation;
      const endRotation = startRotation + turns * TAU + extraRotation;
      const startedAt = performance.now();

      this.isSpinning = true;
      this.dispatchEvent(
        new CustomEvent("spinstart", {
          detail: { key: targetKey, item: this.items[targetIndex] },
        }),
      );

      return new Promise((resolve) => {
        const tick = (now) => {
          const elapsed = now - startedAt;
          const progress = clamp(elapsed / duration, 0, 1);
          const eased = easeOutQuart(progress);

          this.rotation =
            startRotation + (endRotation - startRotation) * eased;
          this.draw();

          if (progress < 1) {
            this.animationFrame = requestAnimationFrame(tick);
            return;
          }

          this.rotation = endRotation;
          this.isSpinning = false;
          const selected = this.getSelectedItem();

          this.draw();
          this.dispatchEvent(
            new CustomEvent("spinend", {
              detail: selected,
            }),
          );
          resolve(selected);
        };

        this.animationFrame = requestAnimationFrame(tick);
      });
    }

    spinTo(key, options = {}) {
      return this.spin({ ...options, targetKey: key });
    }

    pickWeightedKey() {
      const total = this.items.reduce(
        (sum, item) => sum + Math.max(0, Number(item.weight) || 0),
        0,
      );

      if (total <= 0) {
        return this.items[Math.floor(Math.random() * this.items.length)].key;
      }

      let cursor = Math.random() * total;
      for (const item of this.items) {
        cursor -= Math.max(0, Number(item.weight) || 0);
        if (cursor <= 0) {
          return item.key;
        }
      }

      return this.items[this.items.length - 1].key;
    }

    getSelectedItem() {
      const index = this.getSelectedIndex();
      return {
        key: this.items[index].key,
        item: this.items[index],
        index,
      };
    }

    getSelectedIndex() {
      const step = TAU / this.items.length;
      const localPointerAngle = normalize(
        this.config.pointerAngle - this.rotation - this.config.startAngle,
      );
      return Math.floor(localPointerAngle / step) % this.items.length;
    }

    draw() {
      if (!this.geometry || !this.items.length) {
        return;
      }

      const ctx = this.ctx;
      const g = this.geometry;

      ctx.clearRect(0, 0, g.width, g.height);
      this.drawAmbient(ctx, g);
      this.drawOuterRings(ctx, g);
      this.drawWheel(ctx, g);
      this.drawPointer(ctx, g);
      this.drawCenterButton(ctx, g);
    }

    drawAmbient(ctx, g) {
      const glow = ctx.createRadialGradient(
        g.cx,
        g.cy,
        g.outer * 0.1,
        g.cx,
        g.cy,
        g.outer * 1.25,
      );
      glow.addColorStop(0, "rgba(241, 75, 83, 0.2)");
      glow.addColorStop(0.48, "rgba(37, 47, 74, 0.18)");
      glow.addColorStop(1, "rgba(0, 0, 0, 0)");

      ctx.fillStyle = glow;
      ctx.fillRect(0, 0, g.width, g.height);
    }

    drawOuterRings(ctx, g) {
      ctx.save();
      ctx.translate(g.cx, g.cy);

      ctx.beginPath();
      ctx.arc(0, 0, g.outer * 0.965, 0, TAU);
      ctx.lineWidth = g.outer * 0.15;
      ctx.strokeStyle = "rgba(10, 9, 26, 0.9)";
      ctx.stroke();

      ctx.beginPath();
      ctx.arc(0, 0, g.outer * 1.02, 0, TAU);
      ctx.lineWidth = 3;
      ctx.strokeStyle = "rgba(255, 255, 255, 0.16)";
      ctx.stroke();

      ctx.beginPath();
      ctx.arc(0, 0, g.outer * 0.91, 0, TAU);
      ctx.lineWidth = 2;
      ctx.strokeStyle = "rgba(255, 255, 255, 0.08)";
      ctx.stroke();

      ctx.restore();
    }

    drawWheel(ctx, g) {
      ctx.save();
      ctx.translate(g.cx, g.cy);

      ctx.beginPath();
      ctx.arc(0, 0, g.segmentOuter + g.outer * 0.035, 0, TAU);
      ctx.fillStyle = "rgba(9, 8, 25, 0.96)";
      ctx.fill();

      ctx.rotate(this.rotation);
      this.drawSegments(ctx, g);
      this.drawSlotsAndText(ctx, g);

      ctx.restore();
    }

    drawSegments(ctx, g) {
      const step = TAU / this.items.length;
      const gap = Math.min(this.config.gapAngle, step * 0.35);

      for (let index = 0; index < this.items.length; index += 1) {
        const item = this.items[index];
        const start = this.config.startAngle + index * step + gap / 2;
        const end = this.config.startAngle + (index + 1) * step - gap / 2;
        const gradient = ctx.createRadialGradient(
          0,
          0,
          g.segmentInner,
          0,
          0,
          g.segmentOuter,
        );
        const colors = normalizeColors(item.colors);

        gradient.addColorStop(0, colors[0]);
        gradient.addColorStop(0.65, colors[1]);
        gradient.addColorStop(1, colors[2]);

        ctx.save();
        ctx.shadowColor = "rgba(0, 0, 0, 0.38)";
        ctx.shadowBlur = 12;
        ctx.shadowOffsetY = 4;
        petalPath(ctx, start, end, {
          innerRadius: g.segmentInner,
          outerRadius: g.segmentOuter,
          cornerRadius: item.petalCornerRadius || g.petalCornerRadius,
          sideCurve: item.petalSideCurve ?? this.config.petalSideCurve,
        });
        ctx.fillStyle = gradient;
        ctx.fill();
        ctx.restore();

        ctx.save();
        petalPath(ctx, start, end, {
          innerRadius: g.segmentInner,
          outerRadius: g.segmentOuter,
          cornerRadius: item.petalCornerRadius || g.petalCornerRadius,
          sideCurve: item.petalSideCurve ?? this.config.petalSideCurve,
        });
        ctx.clip();
        this.drawSegmentGloss(ctx, g, start, end);
        ctx.restore();

        ctx.save();
        petalPath(ctx, start, end, {
          innerRadius: g.segmentInner,
          outerRadius: g.segmentOuter,
          cornerRadius: item.petalCornerRadius || g.petalCornerRadius,
          sideCurve: item.petalSideCurve ?? this.config.petalSideCurve,
        });
        ctx.lineWidth = 2;
        ctx.strokeStyle = "rgba(255, 255, 255, 0.08)";
        ctx.stroke();
        ctx.restore();
      }
    }

    drawSegmentGloss(ctx, g, start, end) {
      const center = (start + end) / 2;
      const glossPoint = polarPoint(center - 0.12, g.segmentOuter * 0.72);
      const gloss = ctx.createRadialGradient(
        glossPoint.x,
        glossPoint.y,
        0,
        glossPoint.x,
        glossPoint.y,
        g.segmentOuter * 0.54,
      );

      gloss.addColorStop(0, "rgba(255, 255, 255, 0.24)");
      gloss.addColorStop(0.38, "rgba(255, 255, 255, 0.08)");
      gloss.addColorStop(1, "rgba(255, 255, 255, 0)");
      ctx.fillStyle = gloss;
      ctx.fillRect(-g.segmentOuter, -g.segmentOuter, g.segmentOuter * 2, g.segmentOuter * 2);

      ctx.beginPath();
      ctx.arc(0, 0, g.segmentInner + g.segmentWidth * 0.48, start, end);
      ctx.lineWidth = Math.max(5, g.outer * 0.03);
      ctx.lineCap = "round";
      ctx.strokeStyle = "rgba(255, 255, 255, 0.08)";
      ctx.stroke();
    }

    drawSlotsAndText(ctx, g) {
      const step = TAU / this.items.length;

      for (let index = 0; index < this.items.length; index += 1) {
        const item = this.items[index];
        const angle = this.config.startAngle + (index + 0.5) * step;

        this.drawIcon(ctx, g, item, angle);
        this.drawTextBlock(ctx, g, item, angle);
      }
    }

    drawIcon(ctx, g, item, angle) {
      const iconRadius = g.outer * (item.iconRadiusRatio || 0.71);
      const iconSize = item.iconSize || g.iconSize;
      const point = polarPoint(angle, iconRadius, item.iconOffset);
      const image = this.iconCache.get(item.key);
      const hasImage = image && image.complete && image.naturalWidth;

      if (!hasImage && !this.config.showIconSlots) {
        return;
      }

      ctx.save();
      ctx.translate(point.x, point.y);
      ctx.rotate(degToRad(item.iconRotation || 0));

      if (this.config.showIconSlots && !hasImage) {
        ctx.setLineDash([6, 7]);
        ctx.lineWidth = 2;
        ctx.strokeStyle = "rgba(221, 247, 255, 0.38)";
        roundedRect(ctx, -iconSize / 2, -iconSize / 2, iconSize, iconSize, 14);
        ctx.stroke();
      }

      if (hasImage) {
        ctx.shadowColor = "rgba(0, 0, 0, 0.38)";
        ctx.shadowBlur = 12;
        ctx.shadowOffsetY = 5;
        ctx.drawImage(image, -iconSize / 2, -iconSize / 2, iconSize, iconSize);
      }

      ctx.restore();
    }

    drawTextBlock(ctx, g, item, angle) {
      const mainLines = normalizeTextLines(item);
      const note = item.note || "";
      const textRadius = g.outer * (item.textRadiusRatio || 0.53);
      const textPoint = polarPoint(angle, textRadius, item.textOffset);
      const maxWidth = item.textMaxWidth || g.textMaxWidth;
      const baseFontSize = item.fontSize || clamp(g.outer * 0.074, 19, 27);
      const noteFontSize = item.noteFontSize || Math.max(14, baseFontSize * 0.62);
      const mainFontSize = fitFontSize(
        ctx,
        mainLines,
        baseFontSize,
        13,
        maxWidth,
        fontFamily(item.fontWeight || 500),
      );
      const lineHeight = mainFontSize * 1.08;
      const noteGap = note ? noteFontSize * 0.86 : 0;
      const blockHeight =
        mainLines.length * lineHeight + (note ? noteGap + noteFontSize : 0);
      let y = -blockHeight / 2 + lineHeight / 2;
      const rotation = readableTangent(angle) + degToRad(item.textRotation || 0);

      ctx.save();
      ctx.translate(textPoint.x, textPoint.y);
      ctx.rotate(rotation);
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.lineJoin = "round";

      for (const line of mainLines) {
        drawText(ctx, line, 0, y, {
          font: `${item.fontWeight || 500} ${mainFontSize}px ${fontFamily()}`,
          fill: item.textColor || "rgba(255, 255, 255, 0.94)",
          stroke: "rgba(10, 10, 18, 0.45)",
          strokeWidth: Math.max(3, mainFontSize * 0.14),
          maxWidth,
        });
        y += lineHeight;
      }

      if (note) {
        y += noteGap;
        drawText(ctx, note, 0, y - noteFontSize / 2, {
          font: `500 ${noteFontSize}px ${fontFamily()}`,
          fill: item.noteColor || "rgba(196, 249, 252, 0.76)",
          stroke: "rgba(10, 10, 18, 0.36)",
          strokeWidth: 2,
          maxWidth,
        });
      }

      ctx.restore();
    }

    drawPointer(ctx, g) {
      const tipY = g.cy - g.centerRadius * 1.62;
      const baseY = g.cy - g.centerRadius * 0.7;
      const halfWidth = g.centerRadius * 0.3;

      ctx.save();
      ctx.shadowColor = "rgba(255, 94, 63, 0.56)";
      ctx.shadowBlur = 20;
      ctx.beginPath();
      ctx.moveTo(g.cx, tipY);
      ctx.lineTo(g.cx - halfWidth, baseY);
      ctx.lineTo(g.cx + halfWidth, baseY);
      ctx.closePath();

      const pointerGradient = ctx.createLinearGradient(g.cx, tipY, g.cx, baseY);
      pointerGradient.addColorStop(0, "#ffb04e");
      pointerGradient.addColorStop(1, "#ee4948");
      ctx.fillStyle = pointerGradient;
      ctx.fill();
      ctx.restore();
    }

    drawCenterButton(ctx, g) {
      const radius = g.centerRadius;
      const cx = g.cx;
      const cy = g.cy;

      ctx.save();
      const outerGlow = ctx.createRadialGradient(cx, cy, radius * 0.4, cx, cy, radius * 1.85);
      outerGlow.addColorStop(0, "rgba(255, 71, 63, 0.78)");
      outerGlow.addColorStop(0.58, "rgba(255, 71, 76, 0.24)");
      outerGlow.addColorStop(1, "rgba(60, 236, 224, 0.18)");
      ctx.fillStyle = outerGlow;
      ctx.beginPath();
      ctx.arc(cx, cy, radius * 1.88, 0, TAU);
      ctx.fill();

      ctx.shadowColor = "rgba(240, 23, 60, 0.72)";
      ctx.shadowBlur = 20;
      ctx.beginPath();
      ctx.arc(cx, cy, radius * 1.08, 0, TAU);
      ctx.fillStyle = "#f5224e";
      ctx.fill();
      ctx.restore();

      ctx.save();
      const buttonGradient = ctx.createRadialGradient(
        cx - radius * 0.35,
        cy - radius * 0.46,
        radius * 0.18,
        cx,
        cy,
        radius * 1.2,
      );
      buttonGradient.addColorStop(0, "#ff8845");
      buttonGradient.addColorStop(0.62, "#f45737");
      buttonGradient.addColorStop(1, "#ec174a");

      ctx.beginPath();
      ctx.arc(cx, cy, radius, 0, TAU);
      ctx.fillStyle = buttonGradient;
      ctx.fill();

      ctx.beginPath();
      ctx.arc(cx, cy, radius * 0.94, 0, TAU);
      ctx.lineWidth = Math.max(2, radius * 0.035);
      ctx.strokeStyle = "rgba(255, 181, 91, 0.32)";
      ctx.stroke();

      drawText(ctx, "GO", cx, cy + radius * 0.03, {
        font: `700 ${radius * 0.45}px ${fontFamily()}`,
        fill: "rgba(255, 255, 255, 0.96)",
        stroke: "rgba(72, 20, 31, 0.44)",
        strokeWidth: 4,
        maxWidth: radius * 1.5,
      });
      ctx.restore();
    }
  }

  function normalize(value) {
    return ((value % TAU) + TAU) % TAU;
  }

  function clamp(value, min, max) {
    return Math.min(max, Math.max(min, value));
  }

  function randomBetween(min, max) {
    return min + Math.floor(Math.random() * (max - min + 1));
  }

  function easeOutQuart(value) {
    return 1 - Math.pow(1 - value, 4);
  }

  function degToRad(value) {
    return (Number(value) || 0) * (Math.PI / 180);
  }

  function normalizeColors(colors) {
    if (!Array.isArray(colors)) {
      return ["#48c2cd", "#3195a5", "#166f81"];
    }

    if (colors.length === 1) {
      return [colors[0], colors[0], colors[0]];
    }

    if (colors.length === 2) {
      return [colors[0], colors[0], colors[1]];
    }

    return colors;
  }

  function polarPoint(angle, radius, offset = {}) {
    const radial = {
      x: Math.cos(angle),
      y: Math.sin(angle),
    };
    const tangent = {
      x: -Math.sin(angle),
      y: Math.cos(angle),
    };
    const radialOffset = offset.radial || 0;
    const tangentOffset = offset.tangent || 0;

    return {
      x: radial.x * (radius + radialOffset) + tangent.x * tangentOffset,
      y: radial.y * (radius + radialOffset) + tangent.y * tangentOffset,
    };
  }

  function petalPath(ctx, start, end, options) {
    const innerRadius = options.innerRadius;
    const outerRadius = options.outerRadius;
    const cornerRadius = Math.min(
      options.cornerRadius,
      (outerRadius - innerRadius) * 0.38,
      ((end - start) * outerRadius) * 0.2,
    );
    const sideCurve = Math.min(options.sideCurve || 0, (end - start) * 0.18);
    const outerCornerAngle = cornerRadius / outerRadius;
    const innerCornerAngle = Math.min(
      (cornerRadius * 0.34) / Math.max(innerRadius, 1),
      (end - start) * 0.16,
    );
    const startInner = polarPoint(start + innerCornerAngle, innerRadius);
    const startSideControl = polarPoint(
      start + sideCurve,
      innerRadius + (outerRadius - innerRadius) * 0.52,
    );
    const startOuterInset = polarPoint(start, outerRadius - cornerRadius);
    const startOuterCorner = polarPoint(start, outerRadius);
    const endOuterCorner = polarPoint(end, outerRadius);
    const endOuterInset = polarPoint(end, outerRadius - cornerRadius);
    const endSideControl = polarPoint(
      end - sideCurve,
      innerRadius + (outerRadius - innerRadius) * 0.52,
    );
    const endInner = polarPoint(end - innerCornerAngle, innerRadius);

    ctx.beginPath();
    ctx.moveTo(startInner.x, startInner.y);
    ctx.quadraticCurveTo(
      startSideControl.x,
      startSideControl.y,
      startOuterInset.x,
      startOuterInset.y,
    );
    ctx.quadraticCurveTo(
      startOuterCorner.x,
      startOuterCorner.y,
      Math.cos(start + outerCornerAngle) * outerRadius,
      Math.sin(start + outerCornerAngle) * outerRadius,
    );
    ctx.arc(0, 0, outerRadius, start + outerCornerAngle, end - outerCornerAngle);
    ctx.quadraticCurveTo(
      endOuterCorner.x,
      endOuterCorner.y,
      endOuterInset.x,
      endOuterInset.y,
    );
    ctx.quadraticCurveTo(
      endSideControl.x,
      endSideControl.y,
      endInner.x,
      endInner.y,
    );
    ctx.arc(0, 0, innerRadius, end - innerCornerAngle, start + innerCornerAngle, true);
    ctx.closePath();
  }

  function readableTangent(angle) {
    let rotation = angle + Math.PI / 2;
    const normalized = normalize(rotation);

    if (normalized > Math.PI / 2 && normalized < (Math.PI * 3) / 2) {
      rotation += Math.PI;
    }

    return rotation;
  }

  function normalizeTextLines(item) {
    if (Array.isArray(item.lines)) {
      return item.lines.map(String);
    }

    if (item.label) {
      return String(item.label)
        .split(/\n/)
        .map((line) => line.trim())
        .filter(Boolean);
    }

    return [String(item.key)];
  }

  function fontFamily() {
    return 'Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif';
  }

  function fitFontSize(ctx, lines, startSize, minSize, maxWidth, family) {
    let size = startSize;

    while (size > minSize) {
      ctx.font = `500 ${size}px ${family}`;
      const widest = lines.reduce(
        (max, line) => Math.max(max, ctx.measureText(line).width),
        0,
      );

      if (widest <= maxWidth) {
        return size;
      }

      size -= 1;
    }

    return minSize;
  }

  function drawText(ctx, text, x, y, options) {
    ctx.font = options.font;
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";

    if (options.strokeWidth) {
      ctx.lineWidth = options.strokeWidth;
      ctx.strokeStyle = options.stroke;
      ctx.strokeText(text, x, y, options.maxWidth);
    }

    ctx.fillStyle = options.fill;
    ctx.fillText(text, x, y, options.maxWidth);
  }

  function roundedRect(ctx, x, y, width, height, radius) {
    const safeRadius = Math.min(radius, width / 2, height / 2);

    if (ctx.roundRect) {
      ctx.beginPath();
      ctx.roundRect(x, y, width, height, safeRadius);
      return;
    }

    ctx.beginPath();
    ctx.moveTo(x + safeRadius, y);
    ctx.lineTo(x + width - safeRadius, y);
    ctx.quadraticCurveTo(x + width, y, x + width, y + safeRadius);
    ctx.lineTo(x + width, y + height - safeRadius);
    ctx.quadraticCurveTo(x + width, y + height, x + width - safeRadius, y + height);
    ctx.lineTo(x + safeRadius, y + height);
    ctx.quadraticCurveTo(x, y + height, x, y + height - safeRadius);
    ctx.lineTo(x, y + safeRadius);
    ctx.quadraticCurveTo(x, y, x + safeRadius, y);
  }

  const canvas = document.getElementById("rewardWheel");
  const result = document.getElementById("spinResult");
  const wheel = new TurntableCanvas(canvas, wheelOptions);

  wheel.addEventListener("spinstart", () => {
    result.textContent = "";
  });

  wheel.addEventListener("spinend", (event) => {
    const item = event.detail.item;
    result.textContent = normalizeTextLines(item).join(" ");
  });

  window.TurntableCanvas = TurntableCanvas;
  window.rewardWheel = wheel;
  window.rewardWheelOptions = wheelOptions;
})();
